-- PC-AC 2026: matriz oficial dos demais 5 cargos do edital nº 001/2026 – SEAD/PCAC
-- (Delegado, Papiloscopista Policial, Perito Criminal, Auxiliar de Necropsia e Perito
-- Médico-Legista). Fonte: ANEXO III do edital oficial, publicado no DOE/AC em 06/11/2026,
-- já extraído em src/data/pcAcreVerticalizado.ts (usado também na área verticalizada
-- /dashboard/pc-acre-edital). Segue o mesmo padrão da migração do cargo Oficial
-- Investigador (20261107090000_pcac_2026_oficial_investigador_verticalizado.sql).

insert into public.content_sources (source_type, title, issuer, url, published_on, status, notes)
values (
  'edital',
  'Edital nº 001/2026 – SEAD/PCAC – Delegado de Polícia Civil',
  'Secretaria de Estado de Administração / Polícia Civil do Estado do Acre / IDECAN',
  'https://www.diario.ac.gov.br/#pcac-2026-delegado',
  '2026-11-06',
  'vigente',
  'Edital oficial. 8 vagas (lotação central). Remuneração: R$ 19.505,66.'
)
on conflict (url) do update set title=excluded.title, issuer=excluded.issuer, published_on=excluded.published_on, status=excluded.status, notes=excluded.notes, checked_at=now();

insert into public.syllabus_editions (contest_name, role_name, contest_year, exam_board, source_id, status)
select 'Polícia Civil do Acre', 'Delegado de Polícia Civil', 2026, 'IDECAN', id, 'active'
from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-delegado'
on conflict (contest_name, role_name, contest_year) do update set source_id=excluded.source_id, exam_board=excluded.exam_board, status='active';

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Acre' and role_name='Delegado de Polícia Civil' and contest_year=2026
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, v.block_name, v.discipline, v.topic_order, v.topic_text
from edition cross join (values
  ('Conhecimentos básicos', 'Raciocínio Lógico', 1, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 2, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 3, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos', 'Direito Penal', 1, 'Princípios e garantias penais fundamentais: legalidade, anterioridade, irretroatividade, culpabilidade, humanidade, insignificância, intervenção mínima, fragmentariedade, subsidiariedade e proporcionalidade. Disposições constitucionais aplicáveis ao direito penal. Lei penal. 3.1 Características, fontes, interpretação e integração; analogia. 3.2 Aplicação da lei penal no tempo: irretroatividade e retroatividade benéfica; lei penal excepcional e temporária. 3.3 Aplicação da lei penal no espaço: territorialidade e extraterritorialidade. 3.4 Contagem de prazos. 3.5 Conflito aparente de normas. 3.6 Imunidades. Teoria geral do crime. 4.1 Crime e contravenção penal: conceito, objeto e sujeitos; bem jurídico. 4.2 Teorias da ação. 4.3 Fato típico: conduta, resultado, relação de causalidade e imputação objetiva; tipicidade formal e material; causas de exclusão da tipicidade. 4.4 Dolo, culpa e preterdolo; crimes agravados pelo resultado. 4.5 Consumação e tentativa; desistência voluntária, arrependimento eficaz, arrependimento posterior e crime impossível. 4.6 Erro de tipo, erro sobre a pessoa e erro determinado por terceiro; descriminantes putativas. 4.7 Ilicitude e causas de exclusão da ilicitude. 4.8 Culpabilidade e causas de exclusão: imputabilidade, erro de proibição, coação moral irresistível e obediência hierárquica. 4.9 Condições objetivas de punibilidade. Concurso de pessoas: autoria, coautoria e participação; comunicabilidade de elementares e circunstâncias. Concurso de crimes: concurso material, concurso formal e crime continuado. Teoria geral da pena. 7.1 Penas privativas de liberdade e regimes de cumprimento. 7.2 Penas restritivas de direitos. 7.3 Pena de multa. 7.4 Cominação e aplicação da pena; dosimetria. 7.5 Suspensão condicional da pena e livramento condicional. 7.6 Efeitos da condenação e reabilitação. Medidas de segurança. Ação penal. Extinção da punibilidade: conceito, causas gerais e específicas, momentos de ocorrência. 10.1 Prescrição: conceito, espécies, prazos, termos iniciais, causas impeditivas, suspensivas e interruptivas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a propriedade imaterial. Crimes contra a organização do trabalho. Crimes contra o sentimento religioso e contra o respeito aos mortos. Crimes contra a dignidade sexual. Crimes contra a família. Crimes contra a incolumidade pública. Crimes contra a paz pública. Crimes contra a fé pública. Crimes contra a administração pública: crimes praticados por funcionário público e por particular; crimes em licitações e contratos administrativos; crimes contra a administração da justiça; crimes contra as finanças públicas. Crimes contra o Estado democrático de direito. Concurso de Crimes. Entendimento dos tribunais superiores acerca dos institutos de direito penal.'),
  ('Conhecimentos jurídicos', 'Direito Processual Penal', 2, 'Disposições preliminares do Código de Processo Penal; fontes, interpretação e analogia. Princípios constitucionais e processuais penais: devido processo legal, contraditório, ampla defesa, presunção de inocência, juiz natural e publicidade. Sistemas processuais inquisitório, acusatório e misto; sistema acusatório brasileiro e juiz das garantias. Aplicação da lei processual penal no tempo, no espaço e em relação às pessoas; imunidades. Inquérito policial. 5.1 Natureza, conceito, finalidade, características, titularidade e valor probatório. 5.2 Formas de instauração; notitia criminis e delatio criminis. 5.3 Diligências e procedimentos investigativos. 5.4 Indiciamento. 5.5 Garantias do investigado e atuação da defesa na investigação. 5.6 Conclusão, prazos, relatório final e arquivamento. 5.7 Vícios do inquérito policial. Atribuições do delegado de polícia na investigação criminal (Lei nº 12.830/2013). Ação penal: conceito, espécies e condições; representação, requisição, queixa-crime e decadência. Acordo de não persecução penal. Ação civil ex delicto. Jurisdição e competência. 10.1 Critérios de determinação e modificação. 10.2 Incompetência. 10.3 Conexão, continência e prevenção. 10.4 Conflitos de competência. Questões e processos incidentes; medidas assecuratórias; restituição de coisas apreendidas. Provas. 12.1 Conceito, objeto, classificação e sistemas de valoração. 12.2 Ônus da prova. 12.3 Provas ilícitas, ilegítimas e derivadas. 12.4 Meios de prova: perícias e exame de corpo de delito, interrogatório, confissão, testemunhas, reconhecimento de pessoas e coisas, acareação, documentos e indícios. 12.5 Meios de obtenção de prova; prova digital. 12.6 Cadeia de custódia. 12.7 Busca e apreensão pessoal e domiciliar: requisitos, restrições e horários. 12.8 Interceptação telefônica e telemática; afastamento de sigilos. Sujeitos do processo: juiz, Ministério Público, acusado e seu defensor, assistente, auxiliares da justiça, peritos e intérpretes; impedimentos e suspeições. Prisão. 14.1 Conceito, espécies, mandado de prisão e cumprimento; prisão especial. 14.2 Prisão em flagrante. 14.3 Prisão preventiva. 14.4 Prisão temporária. Medidas cautelares diversas da prisão; liberdade provisória; fiança. Audiência de custódia. Juizados especiais criminais; termo circunstanciado de ocorrência. Citações e intimações. Procedimentos comuns e especiais; Tribunal do Júri; processo dos crimes de responsabilidade dos funcionários públicos. Sentença penal e coisa julgada. Nulidades absolutas e relativas. Recursos em geral; ações autônomas de impugnação: habeas corpus, mandado de segurança em matéria criminal e revisão criminal. Entendimento dos tribunais superiores acerca dos institutos de direito processual penal.'),
  ('Conhecimentos jurídicos', 'Legislação Penal e Processual Penal Especial', 3, 'Lei de Introdução ao Código Penal (Decreto-Lei nº 3.914/1941). Contravenções penais (Decreto- Lei nº 3.688/1941). Crimes hediondos (Lei nº 8.072/1990). Lei de Drogas (Lei nº 11.343/2006). Organizações criminosas (Lei nº 12.850/2013); processo e julgamento colegiado em crimes praticados por organizações criminosas (Lei nº 12.694/2012). Marco Legal do Combate ao Crime Organizado – Lei Raul Jungmann (Lei nº 15.358/2026): crimes de domínio social estruturado e de favorecimento ao domínio social estruturado; normas processuais e operacionais; medidas assecuratórias cautelares e definitivas; ação civil de perdimento de bens. Lavagem de dinheiro (Lei nº 9.613/1998). Terrorismo (Lei nº 13.260/2016). Tráfico de pessoas (Lei nº 13.344/2016). Abuso de autoridade (Lei nº 13.869/2019). Tortura (Lei nº 9.455/1997). Estatuto do Desarmamento (Lei nº 10.826/2003). Prisão temporária (Lei nº 7.960/1989). Interceptação das comunicações telefônicas e telemáticas e captação ambiental (Lei nº 9.296/1996). Identificação criminal (Lei nº 12.037/2009). Investigação criminal conduzida pelo delegado de polícia (Lei nº 12.830/2013). Infrações penais de repercussão interestadual ou internacional que exigem repressão uniforme (Lei nº 10.446/2002). Juizados especiais criminais (Lei nº 9.099/1995). Violência doméstica e familiar contra a mulher (Lei nº 11.340/2006). Violência doméstica e familiar contra a criança e o adolescente (Lei nº 14.344/2022). Depoimento especial de crianças e adolescentes (Lei nº 13.431/2017). Estatuto da Criança e do Adolescente (Lei nº 8.069/1990): crimes, inclusive corrupção de menores (art. 244-B), infrações administrativas e apuração de ato infracional. Crimes previstos no Estatuto da Pessoa Idosa (Lei nº 10.741/2003). Crimes previstos no Estatuto da Pessoa com Deficiência (Lei nº 13.146/2015). Crimes resultantes de preconceito (Lei nº 7.716/1989). Crimes ambientais (Lei nº 9.605/1998). Crimes de trânsito (arts. 291 a 312-B da Lei nº 9.503/1997). Crimes cibernéticos e provas digitais (Lei nº 12.737/2012, Lei nº 14.155/2021 e Marco Civil da Internet – Lei nº 12.965/2014). Crimes contra a ordem tributária, econômica e contra as relações de consumo (Lei nº 8.137/1990 e arts. 61 a 80 da Lei nº 8.078/1990). Crimes contra a ordem econômica e o sistema de estoques de combustíveis (Lei nº 8.176/1991). Crimes contra o Sistema Financeiro Nacional (Lei nº 7.492/1986). Proteção a vítimas e testemunhas (Lei nº 9.807/1999). Crimes de responsabilidade de prefeitos e vereadores (Decreto-Lei nº 201/1967). Estatuto do Índio (Lei nº 6.001/1973): disposições penais. Estatuto da Advocacia (Lei nº 8.906/1994): prerrogativas do advogado na investigação criminal e crime de violação de prerrogativas (arts. 7º e 7º-B). Lei de Execução Penal (Lei nº 7.210/1984): arts. 41-A, 41-B, 52 e 112.'),
  ('Conhecimentos jurídicos', 'Direito Constitucional', 4, 'Teoria da Constituição: conceito, objeto, elementos, classificações e supremacia constitucional. Constitucionalismo e neoconstitucionalismo. Poder constituinte originário, derivado, decorrente e difuso; reforma e mutação constitucional. Interpretação constitucional; eficácia e aplicabilidade das normas constitucionais; bloco de constitucionalidade. Controle de constitucionalidade. 5.1 Controle difuso e concentrado. 5.2 Ação direta de inconstitucionalidade, ação declaratória de constitucionalidade, arguição de descumprimento de preceito fundamental e ação direta de inconstitucionalidade por omissão. 5.3 Efeitos das decisões e modulação temporal. Direitos e garantias fundamentais. 6.1 Direitos e deveres individuais e coletivos. 6.2 Direitos sociais. 6.3 Nacionalidade e direitos políticos. 6.4 Remédios constitucionais. 6.5 Tratados internacionais de direitos humanos e sua posição no ordenamento jurídico brasileiro. Organização político-administrativa do Estado; repartição de competências; intervenção federal e estadual. Organização dos Poderes. 8.1 Poder Legislativo, processo legislativo e comissões parlamentares de inquérito. 8.2 Poder Executivo. 8.3 Poder Judiciário e Conselho Nacional de Justiça. Funções essenciais à Justiça: Ministério Público e Conselho Nacional do Ministério Público; Advocacia Pública; Advocacia; Defensoria Pública. Administração Pública e servidores públicos (arts. 37 a 41). Defesa do Estado e das instituições democráticas. 11.1 Estado de defesa e estado de sítio. 11.2 Forças Armadas. 11.3 Segurança pública (art. 144); Sistema Único de Segurança Pública (Lei nº 13.675/2018). Atribuições constitucionais da Polícia Civil. Ordem social: proteção da família, da criança, do adolescente, da pessoa idosa e das pessoas com deficiência; meio ambiente; povos indígenas. Constituição do Estado do Acre.'),
  ('Conhecimentos jurídicos', 'Direito Administrativo', 5, 'Conceito, objeto, fontes e princípios do direito administrativo; regime jurídico-administrativo; sistemas administrativos e sistema adotado no Brasil. Lei de Introdução às Normas do Direito brasileiro aplicada ao direito público (arts. 20 a 30 do Decreto-Lei nº 4.657/1942). Organização administrativa. 3.1 Administração direta e indireta: autarquias, fundações públicas, empresas públicas e sociedades de economia mista. 3.2 Centralização, descentralização e desconcentração. 3.3 Órgãos públicos: conceito e classificação. 3.4 Competência administrativa; avocação e delegação; agente de fato. 3.5 Entidades paraestatais e terceiro setor. Agentes públicos. 4.1 Conceito e espécies; cargo, emprego e função. 4.2 Normas constitucionais. 4.3 Provimento e vacância; estágio probatório; efetividade, estabilidade e vitaliciedade. 4.4 Direitos, deveres e responsabilidade civil, penal e administrativa. Atos administrativos. 5.1 Conceito, elementos, atributos, classificação e espécies. 5.2 Atos vinculados e discricionários; mérito administrativo. 5.3 Vícios do ato administrativo; teoria das nulidades; teoria dos motivos determinantes. 5.4 Anulação, revogação, cassação e convalidação. 5.5 Silêncio administrativo. Poderes e deveres da administração pública. 6.1 Poderes hierárquico, disciplinar, regulamentar e de polícia. 6.2 Polícia administrativa e polícia judiciária. 6.3 Uso e abuso do poder: excesso de poder, desvio de finalidade e omissão. 6.4 Deveres de agir, de probidade, de eficiência e de prestar contas. Processo administrativo (Lei nº 9.784/1999): princípios, fases, recursos administrativos, prescrição e decadência administrativas. Sindicância e processo administrativo disciplinar. Responsabilidade civil do Estado: evolução histórica, teorias subjetivas e objetivas, regime jurídico brasileiro e direito de regresso. Serviços públicos: conceito, princípios, concessão, permissão e autorização. Bens públicos: classificação, afetação e desafetação, regime jurídico e utilização por particulares. Intervenção do Estado na propriedade privada: limitações administrativas, servidão administrativa, requisição, ocupação temporária, tombamento e desapropriação. Licitações e contratos administrativos (Lei nº 14.133/2021): princípios, modalidades, contratação direta, cláusulas exorbitantes, equilíbrio econômico-financeiro, alteração e extinção dos contratos, infrações e sanções administrativas. Controle da administração pública: controle interno e externo; controle administrativo, parlamentar, pelos tribunais de contas e jurisdicional. Improbidade administrativa (Lei nº 8.429/1992 e alterações da Lei nº 14.230/2021). Responsabilização administrativa e civil de pessoas jurídicas por atos contra a administração pública (Lei nº 12.846/2013). Acesso à informação (Lei nº 12.527/2011) e proteção de dados pessoais (Lei nº 13.709/2018).'),
  ('Conhecimentos jurídicos', 'Legislação Institucional', 6, 'Constituição Federal de 1988: art. 144 (segurança pública). Constituição do Estado do Acre: dispositivos relativos à segurança pública e à Polícia Civil. Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis): princípios, diretrizes, competências, organização, atribuições do delegado de polícia, garantias, prerrogativas, direitos, deveres e vedações. Lei Federal nº 12.830/2013 (Investigação criminal conduzida pelo delegado de polícia). Lei Federal nº 13.675/2018 (Sistema Único de Segurança Pública – SUSP e Política Nacional de Segurança Pública e Defesa Social). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre): estrutura, organização, competências, carreira de delegado, direitos, deveres e regime disciplinar. Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre): ingresso, progressão e promoção na carreira. Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres, regime disciplinar, sindicância e processo administrativo disciplinar.'),
  ('Conhecimentos específicos', 'Medicina Legal e Ciências Forenses', 1, 'Conceito, histórico, divisão e importância da medicina legal para o direito. Corpo de delito, perícia médico-legal e peritos; documentos médico-legais. Antropologia forense e identificação humana. 3.1 Identidade, identificação e reconhecimento. 3.2 Papiloscopia, prosopografia, odontologia legal e identificação genética. 3.3 Identificação automatizada e reconhecimento facial automatizado: fundamentos e limites. Traumatologia forense. 4.1 Lesões corporais: classificação médico-legal e jurídica. 4.2 Lesões produzidas por instrumentos contundentes, cortantes, perfurantes, perfurocortantes e perfurocontundentes. 4.3 Lesões por projéteis de arma de fogo comuns e de alta energia; balística forense. 4.4 Lesões por ação térmica, elétrica, química e por baropatias. 4.5 Aspectos médico-legais dos maus-tratos a crianças, adolescentes e pessoas idosas. Asfixiologia forense. Tanatologia forense. 6.1 Conceito e diagnóstico da morte; fenômenos cadavéricos. 6.2 Cronotanatognose, comoriência e premoriência. 6.3 Causas jurídicas da morte; morte súbita e morte suspeita. 6.4 Necropsia e exumação. Sexologia forense: himenologia, gravidez, parto e puerpério; aspectos médico-legais dos crimes contra a dignidade sexual, do aborto e do infanticídio. Toxicologia forense: conceito e importância; intoxicações por álcool, entorpecentes e outras substâncias; embriaguez; exames toxicológicos. Psicopatologia forense. 9.1 Sanidade mental e imputabilidade penal. 9.2 Doenças mentais e transtornos de personalidade com repercussão penal. 9.3 Simulação e dissimulação. 9.4 Perícia psiquiátrica forense. Aspectos médico-legais do testemunho, da confissão e da acareação. Exame de local de crime. Documentoscopia e grafoscopia: conceitos fundamentais; análise de documentos, de escrita e de assinaturas; falsificações documentais.'),
  ('Conhecimentos específicos', 'Criminologia e Vitimologia', 2, 'Conceito, objeto, método e funções da criminologia. Relação entre criminologia, direito penal e política criminal; modelos de política criminal. Escolas criminológicas: escola clássica e escola positiva. Teorias criminológicas. 4.1 Sociologia criminal. 4.2 Teorias da associação diferencial, da anomia, do etiquetamento e do conflito. 4.3 Criminologia crítica e abolicionismo penal. 4.4 Criminologia contemporânea. Vitimologia. 5.1 Conceito e classificação das vítimas. 5.2 Papel da vítima na gênese do delito. 5.3 Vitimização primária, secundária e terciária. 5.4 Políticas de assistência à vítima. Controle social: conceito; controle social formal e informal; agências de controle social. Prevenção do delito: prevenção primária, secundária e terciária. Modelos de reação ao crime: dissuasório, ressocializador e restaurativo. Criminologia e atuação policial. 9.1 Conhecimento criminológico aplicado à investigação criminal e à gestão da segurança pública. 9.2 Perfil criminal. 9.3 Leitura e interpretação de indicadores de criminalidade e estatísticas criminais. Criminologia digital. 10.1 Perfil do criminoso cibernético e análise de crimes digitais. 10.2 Deep web, dark web e ambientes digitais criminógenos. 10.3 Vitimização digital e prevenção de crimes cibernéticos.'),
  ('Conhecimentos específicos', 'Gestão de Polícia Judiciária e Gestão Pública', 3, 'Organização, competências e funcionamento da Polícia Civil; atribuições e prerrogativas do delegado de polícia. Direção de procedimentos investigativos; gestão de equipes, recursos e prazos; planejamento operacional; gestão e preservação de evidências; eficiência e qualidade da investigação. Controle administrativo e disciplinar; ética, deveres e responsabilidades funcionais. Ingresso, estágio probatório e desenvolvimento na carreira; direitos, vantagens, deveres, proibições e incompatibilidades; regime disciplinar, sindicância, processo administrativo disciplinar e penalidades. Gestão pública. 5.1 Governança pública. 5.2 Planejamento e gestão estratégica. 5.3 Eficiência administrativa. 5.4 Gestão por resultados. 5.5 Transparência, integridade e controle na Administração Pública. 5.6 Ética no serviço público. 5.7 Gestão pública aplicada à segurança pública e à atividade policial.')
) as v(block_name, discipline, topic_order, topic_text)
on conflict (edition_id, discipline, topic_order) do update set block_name=excluded.block_name, topic_text=excluded.topic_text, content_status='current';

