insert into public.syllabus_editions (contest_name, role_name, contest_year, exam_board, source_id, status)
select 'Polícia Civil do Acre', 'Papiloscopista Policial', 2026, 'IDECAN', id, 'active'
from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-papiloscopista'
on conflict (contest_name, role_name, contest_year) do update set source_id=excluded.source_id, exam_board=excluded.exam_board, status='active';

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Acre' and role_name='Papiloscopista Policial' and contest_year=2026
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, v.block_name, v.discipline, v.topic_order, v.topic_text
from edition cross join (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos', 'Biologia', 1, 'Citologia. 1.1 Composição química da matéria viva. 1.2 Organização celular das células eucarióticas. 1.3 Estrutura e função dos componentes citoplasmáticos. 1.4 Membrana celular. 1.5 Núcleo. 1.5.1 Estrutura, componentes e funções. 1.5.2 Divisão celular (mitose e meiose, e suas fases). 1.6 Citoesqueleto e movimento celular. Bioquímica. 2.1 Processos de obtenção de energia na célula. 2.2 Principais vias metabólicas. 2.3 Regulação metabólica. 2.4 Metabolismo e regulação da utilização de energia. 2.5 Proteínas e enzimas. Embriologia. 3.1 Gametogênese. 3.2 Fecundação, segmentação e gastrulação. 3.3 Organogênese. 3.4 Anexos embrionários. 3.5 Desenvolvimento embrionário humano. 3.6 Formação dos brotos dos membros superiores e inferiores. Genética. 4.1 Primeira lei de Mendel. 4.2 Probabilidade genética. 4.3 Árvore genealógica. 4.4 Genes letais. 4.5 Herança sem dominância. 4.6 Segunda lei de Mendel. 4.7 Alelos múltiplos: grupos sanguíneos dos sistemas ABO, Rh e MN. 4.8 Determinação do sexo. 4.9 Herança dos cromossomos sexuais. 4.10 Doenças genéticas. Evolução dos processos de identificação humana. 5.1 Aspectos Morfológicos da Identificação. 5.2 Sistema Antropométrico de Alphonse Bertilon. 5.3 Identificação Datiloscópica segundo o método de Vucetich. 5.4 Identidade, Identificação e Individualização. Histologia epitelial. 6.1 Células, estruturas e funções do tecido epitelial. 6.2 Classificação do tecido epitelial. 6.3 Tipos de tecido epitelial. 6.4 Epitélio simples, pseudoestratificado, estratificado e de transição. 6.5 Glândulas exócrinas e endócrinas. 6.6 Funções do tecido epitelial. 6.7 Revestimento de superfícies internas e externas do corpo.'),
  ('Conhecimentos específicos', 'Física', 2, 'Oscilações e ondas: movimento harmônico simples; energia no movimento harmônico simples; ondas em uma corda; energia transmitida pelas ondas; ondas estacionárias; equação de onda. Eletricidade: carga elétrica; condutores e isolantes; campo elétrico; potencial elétrico; corrente elétrica; resistores; capacitores; circuitos elétricos. Óptica: óptica geométrica; reflexão; refração; polarização; interferência. Espectroscopias de absorção e de emissão molecular (fluorescência).'),
  ('Conhecimentos específicos', 'Química', 3, 'QUÍMICA INORGÂNICA: 1.1. Funções inorgânicas; 1.2. Ligações químicas e estrutura molecular; 1.3. Tabela periódica e química dos elementos; 1.4. Noções de química de coordenação (Teoria dos Elétrons de Valência, Teoria do Campo Cristalino e Teoria dos Orbitais Moleculares); 1.5. Cálculo estequiométrico. QUÍMICA ORGÂNICA: 2.1. Teoria estrutural; 2.2. Estereoquímica; 2.3. Funções orgânicas; 2.4. Propriedades físicas dos compostos orgânicos; 2.5. Reatividade de compostos orgânicos. QUÍMICA ANALÍTICA: 3.1. Preparo de soluções; 3.2. Titulometria; 3.3. Complexometria; 3.4. Espectroscopia de absorção na região do ultravioleta, visível e infravermelho; 3.5. Espectroscopia de absorção atômica; 3.6. Espectrometria de massa; 3.7. Processos de extração (Líquido-Líquido, Extração em Fase Sólida, Extração de Voláteis por “Headspace”); 3.8. Técnicas cromatográficas.'),
  ('Conhecimentos específicos', 'Noções de Identificação', 4, 'Lei nº 12.037/2009 (identificação criminal do civilmente identificado). Lei nº 9.454/1997 (número único de registro de identidade civil). Lei nº 7.116/1983 (expedição e validade nacional das carteiras de identidade). Características morfológicas de identificação: gênero, raça, idade, estatura, malformações, sinais profissionais, sinais individuais, tatuagens. Identidade policial e judiciária. 5.1 Bertiolagem. 5.2 Retrato falado. 5.3 Fotografia sinalética. Papiloscopia. 6.1 Impressões datiloscópicas. 6.2 Sistema datiloscópico de Vucetich.'),
  ('Conhecimentos específicos', 'Noções de Medicina e Odontologia Legal', 5, 'Anatomia Crânio- Facial (Ossos e Músculos do Crânio e da Face). Laudos e documentos periciais, modelos e interpretação. Biotipologia. Identificação Craniométrica: estimativa de sexo, estatura, idade, fenótipo, cor da pele, por meio do estudo do crânio. Noções de tanatologia.'),
  ('Conhecimentos específicos', 'Ciências Forenses', 6, 'Medicina Legal: conceito, divisões e importância; perícia médico-legal; antropologia forense; identificação humana; papiloscopia; odontologia legal; identificação por DNA; reconhecimento facial; inteligência artificial aplicada à identificação pericial; sexologia forense; traumatologia forense; lesões corporais; instrumentos lesivos; asfixiologia; balística forense; tanatologia; morte; fenômenos cadavéricos; necropsia; toxicologia forense; intoxicações e exames toxicológicos; psicopatologia forense; imputabilidade penal; perícia psiquiátrica. Criminalística e Documentoscopia: criminalística; vestígios, indícios e evidências; local de crime; cadeia de custódia; preservação de local de crime; documentoscopia; grafoscopia; análise documental; análise de assinaturas; falsificações. Criminologia e Vitimologia: conceito, objeto e métodos da criminologia; escolas criminológicas; criminologia crítica; teorias criminológicas; vitimologia; classificação das vítimas; vitimização; controle social; prevenção do delito; criminologia e política criminal; criminologia aplicada à atuação policial; perfil criminal; análise de indicadores de criminalidade. Criminologia Digital e Investigação Tecnológica: crimes digitais; perfil do criminoso cibernético; deep web; dark web; ambientes digitais criminógenos; vitimização digital; rastreamento de informações; evidências eletrônicas; logs; metadados; redes sociais; preservação de evidências digitais; inteligência cibernética e fontes abertas (OSINT). Noções de Arquivologia.')
) as v(block_name, discipline, topic_order, topic_text)
on conflict (edition_id, discipline, topic_order) do update set block_name=excluded.block_name, topic_text=excluded.topic_text, content_status='current';

