with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Acre' and role_name='Perito Criminal' and contest_year=2026
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, v.block_name, v.discipline, v.topic_order, v.topic_text
from edition cross join (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos (comum a todas as áreas)', 'Criminalística, Documentação Pericial, Balística, Documentoscopia e Perícias em Local', 1, 'Criminalística. 1.1 Conceito, definições, objetivos, princípios e postulados. 1.2 Áreas de atuação da criminalística e modalidades de perícias criminais. 1.3 Prova: conceito e objeto; tipos de prova (confessional, testemunhal, documental e pericial); formas direta e indireta. 1.4 Corpo de delito: conceito. 1.5 Locais de crime: definição, classificação, isolamento, preservação e levantamento. 1.6 Vestígios e indícios encontrados nos locais de crime; cadeia de custódia. Documentação pericial: fotografia forense, croqui e laudo; elaboração de laudos e resposta a quesitos. Balística forense. Documentoscopia e grafoscopia. Perícia em locais de acidente de trânsito: levantamento, dinâmica e noções de cálculo de velocidade. Noções de perícia em locais de incêndio (arts. 158 e 159 do Código de Processo Penal). Noções de medicina legal. 7.1 Conceitos, importância e divisões da medicina legal. 7.2 Corpo de delito, perícia e peritos em medicina legal. 7.3 Documentos médico-legais. 7.4 Identidade, identificação e reconhecimento; principais métodos de identificação. 7.5 Lesões e mortes por ação contundente, por armas brancas e por projéteis de arma de fogo comuns e de alta energia. 7.6 Conceito e diagnóstico da morte: fenômenos cadavéricos; cronotanatognose, comoriência e premoriência; exumação; causa jurídica da morte; morte súbita e morte suspeita. 7.7 Modificadores e avaliação pericial da imputabilidade penal e da capacidade civil: doença mental, desenvolvimento mental incompleto ou retardado, perturbação mental. Lei nº 12.030/2009 (perícias oficiais de natureza criminal). Ética e responsabilidade do perito.'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 1 – Ambiental', 1, 'Ecossistemas, Biota e Conservação Ambiental. 1.1 Biota: noções de botânica e taxonomia vegetal; fauna silvestre e sua classificação; evolução, seleção natural, especiação, mutação, deriva genética e fluxo gênico; cadeias alimentares e níveis tróficos; biomas e ecossistemas brasileiros. 1.2 Ecossistemas acreanos: características, importância e estado de conservação. 1.3 Ecologia de populações e comunidades; ecologia de paisagens; biologia da conservação (teoria e prática aplicada). 1.4 Biosfera: noções de climatologia e meteorologia; domínios morfoclimáticos brasileiros; evolução e classificação das formas de relevo; fundamentos de geologia geral e geomorfologia; sistema brasileiro de classificação de solos; principais domínios pedológicos. 1.5 Conservação dos recursos naturais: desenvolvimento sustentável e conservação; licenciamento ambiental; fundamentos de valoração econômica do meio ambiente; pagamento por serviços ambientais, mercados e créditos de carbono; recuperação de áreas degradadas; conceitos de dano e impacto ambiental. Meio Ambiente Urbano e Saneamento. 2.1 Urbanização: plano diretor e Estatuto da Cidade (Lei nº 10.257/2001); zoneamento ambiental e zoneamento ecológico- econômico; noções de saúde pública e epidemiologia; Lei nº 6.766/1979 (parcelamento do solo urbano) e suas alterações. 2.2 Saneamento: sistemas urbanos de saneamento; tratamento de água para abastecimento; tratamento de efluentes para descarte e/ou reuso; tratamento de águas residuárias urbanas e efluentes industriais; Lei nº 11.445/2007 (saneamento básico), com as alterações da Lei nº 14.026/2020; gerenciamento de resíduos sólidos. 2.3 Hidrologia: bacias hidrográficas e limnologia; ciclo hidrológico e balanço hídrico; gestão e usos de recursos hídricos; impactos do uso da terra em bacias hidrográficas; drenagem urbana; potência hidráulica; medição de vazão, pressão e nível da água; modelagem hidrológica; hidrometria. Poluição, Contaminação e Qualidade Ambiental. 3.1 Poluição hídrica: conceitos e parâmetros de qualidade da água; Lei nº 9.433/1997 (política de recursos hídricos) e alterações; Resoluções CONAMA nº 274/2000, nº 357/2005 e nº 430/2011; controle e monitoramento de corpos hídricos; avaliação de poluição hídrica; impactos ambientais do saneamento; bioindicadores e ecotoxicologia; uso e manejo de herbicidas, fungicidas, nematicidas e bactericidas; amostragem, coleta e preservação de água; autodepuração em cursos d’água. 3.2 Poluição do solo: conceitos básicos; Lei nº 12.305/2010 (política nacional de resíduos sólidos) e alterações; Resoluções CONAMA nº 404/2008 e nº 420/2009; controle e monitoramento da qualidade de solos; avaliação da poluição em ambientes terrestres; técnicas de análise e remediação; conservação do solo; formas de prevenção e combate à erosão e lixiviação; permeabilidade e percolação; estabilidade de taludes e obras de contenção. 3.3 Poluição atmosférica: fundamentos e conceitos; Lei nº 14.850/2024 (política nacional de qualidade do ar); Resolução CONAMA nº 436 de 2011; controle e monitoramento da qualidade do ar. Gestão Ambiental, Silvicultura e Proteção Florestal. 4.1 Inventário florestal: levantamentos fitogeográficos, fitoecológicos e florísticos; cálculo de áreas e produção florestal; avaliação fitossanitária de espécies florestais. 4.2 Práticas silviculturais e manejo florestal: usos sustentáveis dos recursos florestais; produtos madeireiros e não madeireiros; ecofisiologia vegetal; espécies da flora brasileira de uso econômico e tradicional; espécies exóticas invasoras no Brasil e no Acre; espécies com restrição de corte no Estado do Acre. 4.3 Botânica econômica: aplicações na produção de alimentos, energia e celulose. 4.4 Gestão ambiental: planejamento e políticas de conservação. 4.5 Proteção florestal: prevenção e combate a incêndios; controle de pragas e doenças; manejo de bacias hidrográficas. Biotecnologia Florestal. 5.1 Biocombustíveis e energias renováveis. 5.2 Controle biológico e aplicações ambientais. 5.3 Melhoramento florestal e biotecnologia aplicada à conservação. Geoprocessamento e Posicionamento Terrestre. 6.1 Geoprocessamento: sistemas de informação geográfica (SIG); princípios de cartografia; fundamentos de geodésia; bancos de dados geográficos; disponibilização e consumo de dados espaciais; geoestatística, amostragem e parametrização de dados geoespaciais. 6.2 Sensoriamento remoto: princípios e conceitos; sistemas sensores, características e aplicações; sensoriamento orbital ativo e passivo; noções de aeronaves remotamente pilotadas (ARPs); interpretação de imagens aéreas e orbitais; fundamentos de fotogrametria. 6.3 Geoposicionamento e topografia: sistemas GNSS; conceitos de posicionamento por GPS diferencial (DGPS); levantamentos topográficos: métodos e aplicações em áreas rurais. Perícia ambiental: perícia em crimes contra a fauna e a flora; desmatamento e queimadas. 7.1 Lei de Crimes Ambientais (Lei nº 9.605/1998) e Código Florestal (Lei nº 12.651/2012).'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 2 – Ciências Biológicas', 2, 'Fundamentos Teóricos e Conceituais. 1.1 Biologia dos tecidos e das células. 1.1.1 Conceitos básicos da célula e dos tecidos animais e vegetais. 1.1.2 Química da célula. 1.1.3 Biomoléculas: estrutura e função. 1.1.4 Proteínas e enzimas. 1.1.5 Mecanismos de ação e cinética enzimática. 1.1.6 Inibição enzimática. 1.1.7 Função e interação dos componentes e revestimentos celulares. 1.1.8 Divisão celular: mitose e meiose. 1.2 Estrutura e Propriedades do DNA/RNA. 1.2.1 DNA e RNA: Composição química, estrutura e função dos ácidos nucleicos, replicação, transcrição, tradução, mutação, recombinação, regulação gênica e reparo do DNA, propriedades físico-químicas (desnaturação, hibridização). 1.2.2 Genoma Humano: Organização cromossômica, estrutura dos genes, DNA nuclear, DNA mitocondrial. 1.2.3 Genoma Não Humano: Noções de genoma nuclear, mitocondrial e plastidial de espécies animais, vegetais e fúngicas. 1.3 Polimorfismos Genéticos e Herança. 1.3.1 STR (Short Tandem Repeats): Repetições curtas em tandem, padrão de herança mendeliana - aplicações forenses. 1.3.2 SNP (Single Nucleotide Polymorphism): Variações de base única, aplicações em ancestralidade, fenotipagem e outras. 1.3.3 Marcadores Uniparentais: Cromossomo Y (herança paterna) e DNA mitocondrial (herança materna). 1.3.4 Aplicações forenses. Metodologias e Técnicas em Genética Forense. 2.1 Vestígio Biológico. 2.2 Coleta de vestígio biológico em local de crime. 2.3 Cadeia de Custódia de Vestígio Biológico. 2.4 Tipos de Amostras biológicas. 2.4.1 Amostras questionadas. 2.4.2 Amostras de referência. 2.5 Testes diagnósticos para sangue, sêmen e saliva. 2.6 Técnicas de Amostragem. 2.7 Técnicas de Extração e Purificação do DNA. 2.8 Quantificação do DNA em tempo real. 2.9 Técnica da PCR (reação em cadeia da polimerase). 2.10 Amplificação do DNA. 2.11 Eletroforese em placa e capilar. 2.12 Sequenciamento. 2.12.1 Método de Sanger. 2.12.2 Sequenciamento massivo paralelo. 2.13 Tecnologias emergentes: 2.13.1 DNA rápido. 2.13.2 Predição Fenotípica. 2.13.3 Genealogia Genética Forense. Genética de Populações. 3.1 Estrutura de populações. 3.2 Padrões de herança genética. 3.3 Estimativa de frequências alélicas e genotípicas. 3.4 Equilíbrio de Hardy-Weinberg e aplicações do Teorema de Hardy-Weinberg. 3.5 Parâmetros populacionais (estatística de Wright). 3.6 Desequilíbrio de ligação. 3.7 Endogamia. 3.8 Gargalo genético. 3.9 Análise filogenética. 3.10 Seleção natural, mutação, deriva, fluxo gênico. 3.11 Evolução molecular. Estatística e probabilidade aplicados à Genética Forense. 4.1 Teorema de Bayes. 4.2 Cálculo da razão de verossimilhança (LR). 4.3 Avaliação estatística da evidência nos casos de coincidência de perfis genéticos. 4.4 Avaliação da evidência em Casos de Vínculos Genéticos. Gestão da Qualidade. 5.1 Processo de acreditação laboratorial. 5.2 Estrutura normativa aplicável à Genética Forense. 5.3 Norma ISO/IEC 17025: princípios e aplicações. 5.4 Requisitos técnicos para a realização de auditorias nos laboratórios e bancos que compõem a Rede Integrada de Bancos de Perfis Genéticos (Resolução nº 12, de 01 de agosto de 2019 – Comitê Gestor da RIBPG). 5.5 Ensaios Interlaboratoriais. 5.6 Testes de Proficiência. Bancos de Dados de Perfis Genéticos. 6.1 Bases de funcionamento dos Bancos de Perfis Genéticos – BPGs. 6.2 Histórico dos BPGs. 6.3 Rede Integrada de Bancos de Perfis Genéticos. 6.4 Legislação aplicada aos bancos de perfis genéticos: Lei nº 12.654/2012 e Decreto nº 7.950/2013. Entomologia forense e botânica forense.'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 3 – Engenharia Civil', 3, 'Planejamento de projetos e obras de engenharia: programação e controle. 1.1 Viabilidade, planejamento e controle das construções: técnico, físico-financeiro e econômico. 1.2 ABNT NBR 12721:2006 (versão corrigida 2021): avaliação de custos unitários; preparo de orçamento de construção para incorporação de edifício em condomínio; definição de áreas. 1.3 Segurança e higiene do trabalho. Projeto e execução de edificações. 2.1 Estudos preliminares. 2.2 Terraplenagem e locação da obra. 2.3 Canteiro de obras. 2.4 Fundações. 2.5 Escavações. 2.6 Contenção de taludes e escoramentos. 2.7 Estruturas metálicas, de madeira e de concreto; formas; armação; alvenaria estrutural; estruturas pré-fabricadas. 2.8 Instalações prediais: elétricas, hidráulicas, de esgoto, de telefone e instalações especiais (proteção e vigilância, gás, ar- condicionado, combate a incêndio, ar comprimido, vácuo e água quente). 2.9 Alvenarias e revestimentos. 2.10 Esquadrias. 2.11 Forros. 2.12 Pisos. 2.13 Coberturas. 2.14 Impermeabilização. 2.15 Noções de projeto assistido por computador (CAD). Projeto e execução de rodovias e ferrovias. 3.1 Movimento de terra. 3.2 Projeto geométrico. 3.3 Ensaios geotécnicos principais. 3.4 Pavimentação/superestrutura: projeto, tipos, aplicação e componentes. 3.5 Principais elementos. 3.6 Drenagem. 3.7 Critérios de medição. 3.8 Custos rodoviários. Hidráulica e saneamento básico. 4.1 Redes de água e esgoto. 4.2 Tratamento de água e esgoto. 4.3 Hidráulica aplicada e hidrologia. Materiais de construção civil. 5.1 Aglomerantes e agregados. 5.2 Materiais betuminosos. 5.3 Propriedades físicas e mecânicas. 5.4 Ensaios. 5.5 Sistemas construtivos. Mecânica dos solos. 6.1 Origem e formação dos solos: processos erosivos. 6.2 Índices físicos. 6.3 Caracterização e propriedades dos solos. 6.4 Pressões nos solos. 6.5 Prospecção geotécnica. 6.6 Permeabilidade dos solos; percolação nos solos. 6.7 Compactação, compressibilidade e adensamento dos solos; estimativa de recalques. 6.8 Resistência dos solos ao cisalhamento. 6.9 Empuxos de terra; estruturas de arrimo; estabilidade de taludes, de fundações superficiais e de fundações profundas. Projeto e execução de barragens e hidrelétricas. 7.1 Principais tipos. 7.2 Elementos. 7.3 Mecanismos de ruptura de barragens. Resistência dos materiais e análise estrutural. 8.1 Deformações e análise de tensões. 8.2 Flexão simples; flexão composta; torção; cisalhamento e flambagem. 8.3 Esforços em uma seção: esforço normal; esforço cortante; torção e momento fletor. 8.4 Diagrama de esforços solicitantes. 8.5 Estruturas isostáticas: vigas simples, vigas gerber, quadros, arcos e treliças. 8.6 Estruturas hiperestáticas: métodos dos esforços; método dos deslocamentos. Dimensionamento de estruturas em concreto. 9.1 Características mecânicas e reológicas do concreto. 9.2 Tipos de aço para concreto armado; fabricação do aço; características mecânicas do aço; estados limites; aderência; ancoragem e emendas em barras de armação. 9.3 Dimensionamento de elementos estruturais: pilares, lajes e vigas. 9.4 Detalhamento de armação em concreto armado. 9.5 Concreto protendido: noções gerais e tipos de protensão. 9.6 Concreto premoldado: dimensionamento, detalhamento e montagem. Engenharia legal. 10.1 ABNT NBR 13752:2024 (perícias de engenharia na construção civil). 10.2 Engenharia de avaliações: métodos; depreciação; desapropriações; laudos de avaliação (ABNT NBR 14653-2:2011). 10.3 Fiscalização. 10.3.1 Ensaios de recebimento da obra. 10.3.2 Acompanhamento da aplicação de recursos (medições, emissão de fatura, cálculos de reajustamento). 10.3.3 Controle de execução de obras e serviços. 10.3.4 Análise de documentação técnica: diário de obra, documentos de legalização, ARTs, aditivos contratuais. Engenharia de custos. 11.1 Levantamento de serviços e seus quantitativos. 11.2 Orçamento analítico e sintético. 11.3 Composição analítica de serviços. 11.4 Cronograma físico-financeiro. 11.5 Cálculo de benefício e despesas indiretas (BDI). 11.6 Cálculo de encargos sociais. 11.7 Índices de atualização de custos na construção civil. 11.8 Sistemas referenciais oficiais: SINAPI, novo SICRO — metodologia e conceitos; produtividade e equipamentos. Patologia de obras de engenharia civil. 12.1 Patologia de edificações. 12.2 Patologia de obras de terra. 12.3 Patologia de obras rodoviárias e ferroviárias. 12.4 Patologia de obras hídricas. Obras portuárias. 13.1 Tipos de portos (genéricos e especializados). 13.2 Obras de implantação e principais equipamentos de operação. 13.3 Estruturas de proteção e atracamento. 13.4 Canal de acesso. 13.5 Aspectos construtivos.'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 4 – Informática Forense', 4, 'Fundamentos da computação: Organização e arquitetura de computadores, sistemas operacionais (arquiteturas e componentes, kernel, gerenciador de memória, gerenciador de arquivos, gerenciador de E/S, middleware), processadores (arquiteturas paralelas, multiprocessamento e multicore, hyper-threading, GPUs, arquitetura CUDA e aplicações em processamento vetorial), sistemas distribuídos (modelos de memória compartilhada), tecnologias de virtualização (emuladores, máquinas virtuais, contêineres), RAID (tipos, características e aplicações), sistemas de arquivos NTFS, FAT32, exFAT, EXT3, EXT4, XFS (características, organização e metadados), computação quântica (conceitos envolvidos). Bancos de dados: Arquitetura, modelos lógicos e representação física, bancos de dados multidimensionais (conceitos envolvidos), SGBDs relacionais, linguagem de consulta estruturada (SQL), transações (características e análise de logs), NOSQL. Engenharia reversa de software: Técnicas e ferramentas de descompilação de programas, debuggers, análise de código malicioso (vírus, backdoors, keyloggers, worms e outros), ofuscação de código, compactadores de código executável, malware polimórfico, técnicas de sandboxing, linguagem Assembly. Linguagens de programação: Noções de linguagens de programação orientadas a objetos (objetos, classes, herança, polimorfismo, sobrecarga de métodos), noções de linguagens procedurais (tipos de dados elementares e estruturados, funções e procedimentos), estruturas de controle de fluxo de execução, montadores, compiladores, ligadores e interpretadores, linguagens C, Java, Javascript e Python, desenvolvimento Web (HTML, XML, JSON, APIs REST/GraphQL), análise estática de código fonte (SonarQube). Estruturas de dados e algoritmos: Estruturas de dados (listas, filas, pilhas e árvores), métodos de acesso, busca, inserção e ordenação em estruturas de dados, complexidade de algoritmos, autômatos determinísticos e não-determinísticos. Redes de computadores: Tipos, tecnologias e topologias de redes de computadores, técnicas básicas de comunicação, técnicas de comutação de circuitos, pacotes e células, elementos de interconexão (gateways, hubs, repetidores, bridges, switches, roteadores), arquiteturas e protocolos de redes (modelo OSI e arquitetura TCP/IP, arquitetura cliente-servidor, Ethernet, redes peer-to-peer, comunicação sem fio, redes móveis de dados, protocolos IP, TCP, UDP, SCTP, ARP, TLS, SSL, OSPF, BGP, DNS, DHCP, ICMP, FTP, SFTP, SSH, HTTP, HTTPS, SMTP, IMAP, POP3), deepweb e darkweb, redes TOR, computação em nuvem. Segurança da informação: Normas NBR ISO/IEC nº 27001:2022 e nº 27002:2022, desenvolvimento seguro de aplicações (SDL, CLASP e OWASP Top 10), segurança de contêineres (Docker, Kubernetes e runtime security), autenticação e autorização (características, fundamentos e conceitos envolvidos, Single Sign-On, SAML, OAuth 2.0, OpenId Connect, biometria comportamental, reconhecimento facial, análise de íris, voz, impressão digital, protocolos de autenticação sem senha FIDO2/WebAuthn, múltiplos fatores de autenticação), malware (vírus, keylogger, trojan, spyware, backdoor, worms, rootkit, adware, fileless, ransomware), OSINT, esteganografia, recuperação de dados (principais técnicas de recuperação de arquivos apagados em sistemas de arquivos, ambientes de nuvem AWS, Azure e Google Cloud). Segurança de redes de computadores: Firewall, sistemas de prevenção e detecção de intrusão (IPS e IDS), antivírus, EDR, XDR, SOAR, SIEM, NAT, proxy, VPN, protocolos IPSEC, DNSSEC, DMARC, DKIM, SPF, monitoramento e análise de tráfego (sniffers, traffic shaping), segurança de redes sem fio (EAP, WEP, WPA, WPA2, WPA3, autenticação baseada em contexto, protocolo 802.1X), ataques a redes de computadores (DoS, DDoS, botnets, phishing, zero-day exploits, ping da morte, UDP Flood, MAC flooding, IP spoofing, ARP spoofing, buffer overflow, SQL injection, Cross-Site Scripting, DNS Poisoning, MITRE ATT&CK), frameworks de segurança da informação e segurança cibernética (CIS Controls e NIST CyberSecurity Framework), ameaças persistentes avançadas (APTs). Criptografia: Sistemas criptográficos simétricos e assimétricos, certificação digital, modos de operação de cifras, algoritmos RSA, AES, ECC, IDEA, Twofish, Blowfish, 3DES e RC4, protocolo Diffie-Hellman, hashes criptográficos (algoritmos MD5, SHA-1, SHA-2, SHA-3, colisões), técnicas (força bruta, criptoanálise, canal lateral, ataques de texto conhecido/escolhido, Man-in-the-Middle), protocolo Signal. Sistema Operacional Windows: Sistemas Windows (Desktop e Server), gerenciamento de usuários e permissões de acesso, log de eventos do Windows, registros do Windows, BitLocker. Sistema Operacional Linux: Características do sistema operacional Linux, gerenciamento de usuários e permissões de acesso, configuração, administração e logs de sistema e de serviços (proxy, correio eletrônico, servidor Web, servidor de arquivos), shell e comandos. Sistemas operacionais móveis: Android e iOS (arquitetura, segurança, modelos de permissão, sandboxing, criptografia de dados, gerenciamento de memória e processos, sistemas de arquivos). Governança de TI e Legislação aplicada: ITIL 4 (características gerais), contratações de TI (Lei nº 14.133/2021), Marco Civil da Internet (Lei nº 12.965/2014, responsabilidades de provedores e coleta de logs); Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018); Lei nº 12.737/2012 (crimes informáticos). Inteligência Artificial: Aprendizado de máquina (supervisionado, não supervisionado, semisupervisionado, aprendizado por reforço, análise preditiva), redes neurais e deep learning, LLMs e processamento de linguagem natural, inteligência artificial generativa, deepfakes. Princípios da computação forense: Os crimes cibernéticos e seus vestígios, identificação, isolamento, preservação e coleta de vestígio cibernético; cadeia de custódia do vestígio digital; principais exames realizados em computação forense. Hardware: Placas mãe, processadores, memórias, dispositivos de armazenamento, interfaces de E/S, alimentação. Criptomoedas: Blockchain, Bitcoin, stablecoins, altcoins, hard wallets, cold wallets.'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 5 – Medicina Veterinária', 5, 'Inspeção Industrial e Sanitária de Produtos de Origem Animal: Programas de Controle. 1.1 Boas Práticas de Fabricação (BPF). 1.2 Procedimento Padrão de Higiene Operacional (PPOH) e Análise de Perigos e Pontos Críticos de Controle (APPCC). Análises Microbiológicas e Físico-Químicas de Águas. Análises Microbiológicas e Físico-Químicas de Produtos de Origem Animal. 3.1 Microscopia de alimentos (pesquisa de matérias estranhas). 3.2 Resíduos e contaminantes em produtos de origem animal. 3.3 Identidade e qualidade de produtos de origem animal. Tecnologia de Produtos de Origem Animal. Defesa Sanitária Animal: prevenção, controle, diagnóstico clínico e laboratorial das principais doenças que afetam o comércio e a saúde humana e animal. Epidemiologia. Análise de risco. Bioestatística. Inspeção industrial e higiênico-sanitária de produtos destinados à alimentação humana e animal. 9.1 Métodos de análise e amostragem de produtos destinados à alimentação humana e animal. 9.2 Análises de resíduos e contaminantes microbiológicos e físico-químicos de produtos destinados à alimentação humana e animal. Tipos e funções dos aditivos utilizados em alimentos. Inspeção de produtos de uso veterinário: controle da produção de soros, vacinas e antígenos para uso veterinário. Ensaios de eficácia e segurança para produtos veterinários. Biossegurança. Inspeção de produtos de origem animal. 14.1 Anatomia, fisiologia e patologia dos animais domésticos e animais de corte. Classificação taxonômica e manejo de animais da fauna silvestre brasileira. Análise Patológica: técnicas de necropsia e exames de laboratório necessários para a determinação da causa mortis. Análises ambientais. 17.1 Meio ambiente. 17.2 Conceito e definição de meio abiótico, biota, fauna, flora, comunidade, ecossistema, sucessão ecológica, contaminação, poluição, dano ambiental, recuperação ambiental, reabilitação ambiental, restauração ecológica, espécies nativas, espécies não nativas, espécies exóticas. 17.3 Sensoriamento remoto e geoprocessamento. 17.4 Avaliação de impacto ambiental. 17.5 Valoração de danos ambientais. 17.6 Políticas ambientais. 17.7 Legislação: Constituição Federal (Capítulo VI – Do meio ambiente); Lei nº 6.766/1979; Lei nº 6.938/1981; Lei nº 9.433/1997; Lei nº 9.605/1998 (sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente); Lei nº 9.985/2000; Lei nº 11.105/2005; Lei nº 12.651/2012; Decreto nº 6.514/2008 e alterações; Resolução CONAMA nº 01/1986 e alterações; Resolução CONAMA nº 237/1997; Portarias do MMA sobre espécies ameaçadas; Instrução Normativa IBAMA nº 21/2014. 17.8 Requisitos técnicos da norma ABNT NBR ISO/IEC 17025:2017. 17.9 Técnicas de coleta de espécies animais, vegetais e poluentes. 17.10 Medições de parâmetros ambientais com aparelhos portáteis (oxímetro, condutivímetro, turbidímetro, pHmetro, clinômetro, GPS, decibilímetro). Perícia em crimes contra animais: maus-tratos e zoonoses; art. 32 da Lei nº 9.605/1998, com as alterações da Lei nº 14.064/2020 (maus-tratos a cães e gatos).'),
  ('Conhecimentos específicos (da área escolhida no ato da inscrição)', 'Área 6 – Química', 6, 'Farmacologia geral: subdivisão da farmacologia; classificação das formas farmacêuticas; classificação das drogas. Bases fisiológicas da farmacologia: mediadores químicos; evolução do conceito de mediação química; receptores farmacológicos; receptores pré e pós-sinápticos; interação droga-receptor; mensageiro secundário. Farmacocinética: via de administração de drogas; absorção; biodisponibilidade; meia-vida das drogas; distribuição; biotransformação; excreção. Farmacodinâmica: mecanismos de ação das drogas; interação droga-receptor; relação dose/efeito; sinergismo; tipos de antagonismo; eficácia e potência de uma droga. Drogas que atuam em nível de sistema nervoso central: hipnóticos e sedativos; álcoois alifáticos; anestésicos gerais; estimulantes do sistema nervoso central; neurolépticos; ansiolíticos; antidepressivos; opiáceos; alucinógenos; abuso de drogas; dependência; tolerância. Toxicologia: conceitos básicos de toxicologia; classificação toxicológica; avaliação de toxicidade; monitorização ambiental e biológica; toxicocinética; toxicodinâmica; agentes tóxicos gasosos e voláteis; agentes tóxicos meta-hemoglobinizantes; metais pesados; agentes psicotrópicos; toxicologia laboratorial; toxicologia ambiental; toxicologia forense; casos clinicotoxicológicos. Físico-química. 7.1 Termodinâmica química. 7.2 Equilíbrio e cinética química. Química inorgânica. 8.1 Ligação química e estrutura molecular. 8.2 Ácidos e bases. 8.3 Tabela Periódica e química dos elementos. Química orgânica. 9.1 Ligação química e estrutura molecular em moléculas orgânicas. 9.2 Grupos funcionais. 9.3 Propriedades físicas dos compostos orgânicos. 9.4 Estereoquímica. 9.5 Propriedades químicas dos compostos orgânicos. 9.6 Reações dos compostos orgânicos e seus mecanismos. Química analítica. 10.1 Química analítica qualitativa; química analítica quantitativa; análise gravimétrica. 10.2 Análise estatística de dados experimentais; planejamento de experimentos; validação de metodologias analíticas (RDC ANVISA nº 760/2022). 10.3 Espectroscopia de fluorescência por raios X (EDX); Espectroscopia Raman; espectroscopia por infravermelho com transformada de Fourier (FT-IR). 10.4 Espectrometria de massas: princípios, ionização (EI, APCI, ESI), analisadores de massa (Quadrupolo, Ion Trap, Orbitrap, TOF); Acoplamento cromatografia–espectrometria de massas (GC-MS/MS, LC-MS/MS); cromatografia gasosa com detector por ionização de chama (GC-FID). Noções de biologia celular, microbiologia, histologia e fisiologia aplicadas à perícia. 11.1 Genética forense: análise de DNA nuclear e mitocondrial, polimorfismos genéticos, testes de paternidade, identificação de indivíduos e populações. 11.2 Biologia molecular aplicada à criminalística: PCR, sequenciamento e técnicas de análise de vestígios biológicos. Sistema de gestão da qualidade. 12.1 Definições. 12.2 Requisitos técnicos da norma ABNT NBR ISO/IEC 17025:2017. Legislação sanitária. 13.1 Lei nº 6.360/1976. 13.2 Portaria SVS/MS nº 344/1998 e atualizações. 13.3 RDC Anvisa nº 1.024/2026. Identificação de drogas de abuso; química de explosivos e de resíduos de incêndio.')
) as v(block_name, discipline, topic_order, topic_text)
on conflict (edition_id, discipline, topic_order) do update set block_name=excluded.block_name, topic_text=excluded.topic_text, content_status='current';

insert into public.content_sources (source_type, title, issuer, url, published_on, status, notes)
values (
  'edital',
  'Edital nº 001/2026 – SEAD/PCAC – Auxiliar de Necropsia',
  'Secretaria de Estado de Administração / Polícia Civil do Estado do Acre / IDECAN',
  'https://www.diario.ac.gov.br/#pcac-2026-auxiliar-necropsia',
  '2026-11-06',
  'vigente',
  'Edital oficial. 7 vagas (lotação central). Remuneração: R$ 6.342,07.'
)
on conflict (url) do update set title=excluded.title, issuer=excluded.issuer, published_on=excluded.published_on, status=excluded.status, notes=excluded.notes, checked_at=now();

insert into public.syllabus_editions (contest_name, role_name, contest_year, exam_board, source_id, status)
select 'Polícia Civil do Acre', 'Auxiliar de Necropsia', 2026, 'IDECAN', id, 'active'
from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-auxiliar-necropsia'
on conflict (contest_name, role_name, contest_year) do update set source_id=excluded.source_id, exam_board=excluded.exam_board, status='active';

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Acre' and role_name='Auxiliar de Necropsia' and contest_year=2026
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, v.block_name, v.discipline, v.topic_order, v.topic_text
from edition cross join (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos', 'Anatomia e Fisiologia Humanas, Tanatologia, Biossegurança e Cadeia de Custódia', 1, 'Anatomia e fisiologia humanas. 1.1 Seres vivos: classificação dos seres vivos. 1.2 Célula: célula procariota e eucariota; componentes morfológicos das células; funções das estruturas celulares. 1.3 Posição anatômica, divisões do corpo humano, quadrantes abdominais (órgãos) e topografia. 1.4 Sistema tegumentar: pele, pelos, unhas. 1.5 Sistema muscular. 1.6 Sistema esquelético: funções, divisão anatômica do esqueleto, ossos, crânio, coluna vertebral, articulações. 1.7 Sistema respiratório: função, respiração, órgãos componentes, mecanismo da respiração. 1.8 Sistema cardiovascular: principais funções, sangue, coração, movimentos cardíacos, pulso, vasos sanguíneos, circulação sanguínea. 1.9 Sistema geniturinário: sistema urinário, sistema genital masculino, sistema genital feminino. 1.10 Sistema digestório. 1.11 Sistema nervoso: função, divisão, meninges, sistema nervoso central, sistema nervoso periférico, sistema nervoso visceral, sistema nervoso somático. 1.12 Noções de fisiologia. Tanatologia: fenômenos cadavéricos e cronologia da morte. Técnicas de necropsia: abertura e exame das cavidades, retirada e pesagem de órgãos, coleta e acondicionamento de material, recomposição e sutura. 3.1 Exumação. 3.2 Remoção e transporte de cadáveres. Biossegurança. 4.1 Equipamentos de proteção, limpeza e desinfecção, resíduos de serviços de saúde. 4.2 Prevenção de acidentes e cuidados de ordem pessoal e geral. 4.3 Perigos no ambiente de trabalho: cuidados gerais, substâncias tóxicas, emitentes de vapores venenosos, explosivos e combustíveis, manuseio de material contaminado. Noções de química e de física aplicadas: soluções; densidade; concentração e diluição de soluções; volumetria; estado físico da matéria (sólido, líquido, gasoso); Sistema Internacional de Unidades. Noções de medicina legal. Cadeia de custódia (arts. 158-A a 158-F do Código de Processo Penal). Noções de ética profissional e sigilo. Registros e documentação do serviço: guias de remoção, livros de entrada e saída, noções sobre a declaração de óbito. Lei nº 8.501/1992, que trata da destinação de cadáver não reclamado.')
) as v(block_name, discipline, topic_order, topic_text)
on conflict (edition_id, discipline, topic_order) do update set block_name=excluded.block_name, topic_text=excluded.topic_text, content_status='current';

insert into public.content_sources (source_type, title, issuer, url, published_on, status, notes)
values (
  'edital',
  'Edital nº 001/2026 – SEAD/PCAC – Perito Médico-Legista',
  'Secretaria de Estado de Administração / Polícia Civil do Estado do Acre / IDECAN',
  'https://www.diario.ac.gov.br/#pcac-2026-perito-medico-legista',
  '2026-11-06',
  'vigente',
  'Edital oficial. 4 vagas (lotação central). Remuneração: R$ 14.629,25.'
)
on conflict (url) do update set title=excluded.title, issuer=excluded.issuer, published_on=excluded.published_on, status=excluded.status, notes=excluded.notes, checked_at=now();

insert into public.syllabus_editions (contest_name, role_name, contest_year, exam_board, source_id, status)
select 'Polícia Civil do Acre', 'Perito Médico-Legista', 2026, 'IDECAN', id, 'active'
from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-perito-medico-legista'
on conflict (contest_name, role_name, contest_year) do update set source_id=excluded.source_id, exam_board=excluded.exam_board, status='active';

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Acre' and role_name='Perito Médico-Legista' and contest_year=2026
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, v.block_name, v.discipline, v.topic_order, v.topic_text
from edition cross join (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos (comum às duas especialidades)', 'Medicina Legal', 1, 'Perícias e Peritos. 1.1 Documentos médico-legais. 1.2 Quesitos oficiais. 1.3 Perícias médicas. 1.4 Ética médica e pericial. 1.5 Legislação sobre perícias médico-legais. Antropologia Médico-legal. 2.1 Identidade e identificação. 2.2 Identificação judiciária. Traumatologia Médico-legal. 3.1 Lesões corporais sob o ponto de vista jurídico. 3.2 Energias de Ordem Mecânica. 3.3 Energias de Ordem Química, cáusticos e venenos, embriaguez, toxicomanias. 3.4 Energias de Ordem Física: Efeitos da temperatura, eletricidade, pressão atmosférica, radiações, luz e som. 3.5 Energias de Ordem Físico-Química: Asfixias em geral. Asfixias em espécie: por gases irrespiráveis, por monóxido de carbono, por sufocação direta, por sufocação indireta, por afogamento, por enforcamento, por estrangulamento, por esganadura, por soterramento e por confinamento. 3.6 Energias de Ordem Biodinâmica e Mistas. Tanatologia Médico-legal. 4.1 Tanatognose e cronotanatognose. 4.2 Fenômenos cadavéricos. 4.3 Necropsia, necroscopia. 4.4 Exumação. 4.5 "Causa mortis". 4.6 Morte natural e morte violenta. 4.7 Direitos sobre o cadáver. Sexologia Médico-legal. 5.1 Crimes contra a dignidade sexual e provas periciais. 5.2 Gravidez, parto, puerpério, aborto, infanticídio. 5.3 Reprodução assistida. 5.4 Transtornos da sexualidade e da identidade sexual. Psicopatologia Médico-legal. 6.1 Imputabilidade penal e capacidade civil. 6.2 Limite e modificadores da responsabilidade penal e capacidade civil. 6.3 Repercussões médico-legais dos distúrbios psíquicos. 6.4 Simulação, dissimulação e supersimulação. 6.5 Embriaguez alcoólica. 6.6 Alcoolismo. 6.7 Aspectos jurídicos. 6.8 Toxicofilias. Infortunística. Exames em vivos e em cadáveres; clínica médica e patologia aplicadas; radiologia forense e exames de imagem aplicados à medicina legal; estimativa de idade em vivos e cadáveres. Legislação e ética: Lei nº 12.030/2009; Código de Ética Médica (Resolução CFM nº 2.217/2018), na parte de perícia médica; atendimento à vítima de violência sexual (Lei nº 12.845/2013 e Decreto nº 7.958/2013).'),
  ('Conhecimentos específicos (da especialidade escolhida no ato da inscrição)', 'Medicina Legal Geral (especialidade)', 1, 'Toxicologia forense. 1.1 Os princípios de Direito e de Justiça Criminal aplicados às Ciências Forenses. 1.2 Principais avanços das Ciências Forenses. 1.3 Introdução à Toxicologia Forense. 1.4 Princípios Gerais da Toxicologia. 1.5 Conceitos básicos da Toxicologia Forense. 1.6 O fenômeno da intoxicação. 1.7 Princípios de Neurociências aplicados à Toxicologia Forense. 1.8 Atuação de substâncias psicoativas no organismo humano. 1.8.1 Álcool Etílico. 1.8.2 Barbitúricos. 1.8.3 Benzodiazepínicos. 1.8.4 Opiáceos e Opioides. 1.8.5 Inalantes. 1.8.6 Anfetamínicos. 1.8.7 Ecstasy. 1.8.8 Cocaína e Crack. 1.8.9 Maconha. 1.8.10 Dietilamida do Ácido Lisérgico (LSD). 1.9 Drogas sintéticas. 1.10 Controle de dopagem. 1.11 Entomotoxicologia. 1.12 Análises toxicológicas em matrizes biológicas. 1.13 Praguicidas. 1.14 Gases Tóxicos. 1.15 Tóxicos Metálicos. Patologia (exames laboratoriais). 2.1 Vidraria e equipamentos de laboratório. 2.2 Microscopia óptica. 2.3 Organização e comportamento laboratorial. 2.4 Preparo de amostras. 2.5 Preparo de soluções. 2.6 Esterilização e desinfecção. 2.7 Análise por fracionamento. 2.8 Fotometria. 2.9 Hematologia: preparo de esfregaço sanguíneo, anticoagulantes, série vermelha e série branca, velocidade de sedimentação das hemácias, coagulação sanguínea. 2.10 Imuno-hematologia: sistema ABO dos grupos sanguíneos, sistema RH dos grupos sanguíneos, prova cruzada. 2.11 Bioquímica do sangue: fundamentos básicos, métodos de determinações bioquímicas. 2.12 Urinálise: coleta de urina, características físicas, análise do sedimento urinário, análise de amostra única e urina de 24 h. 2.13 Líquido cefalorraquidiano: caracteres físicos. 2.14 Parasitologia: métodos diagnósticos para parasitos e protozoários, coprocultura, pesquisa de sangue oculto. 2.15 Microbiologia: morfologia bacteriana, tipos de meios de cultura, métodos de coloração, técnicas de bacteriologia. 2.16 Imunologia: coleta e conservação de material, métodos de microscopia, técnicas para identificação de anticorpos, reações sorológicas (aglutinação, precipitação, hemólise), reação antígeno/anticorpo.'),
  ('Conhecimentos específicos (da especialidade escolhida no ato da inscrição)', 'Psiquiatria (especialidade)', 2, 'Introdução à Psiquiatria Forense. A perícia psiquiátrica. História da Psiquiatria Forense. Internações Psiquiátricas. Documentos Médicos. Capacidade de Consentir. Psicopatia. Perícia Criminal. Perícia Civil. Perícias Previdenciárias. Perícias Psicológicas. Burnout. Psiquiatria e Cultura. Psicopatologia forense: classificação das doenças mentais; aspectos médicos e jurídicos, Perícias psiquiátricas em matéria criminal e penitenciária; Psiquiatria Forense da Infância e da Adolescência; Psiquiatria Forense Geriátrica; Exame pericial indireto. Necropsia psicológica; Avaliação da responsabilidade penal; Avaliação de risco de violência; os exames periciais de dependência de drogas e de cessação de dependência. Embriaguez. A questão da “actio libera in causa”; Simulação; Psicologia Judiciária do testemunho; Responsabilidade civil, penal e ética do psiquiatra e do perito psiquiatra; Direitos do doente mental; Internação psiquiátrica involuntária e internação psiquiátrica compulsória; O segredo profissional e o sigilo pericial. Situações de notificação compulsória; Consentimento esclarecido em psiquiatria; Princípios bioéticos e sua aplicação em psiquiatria e psiquiatria forense; A pesquisa em psiquiatria. Aspectos éticos e legais.')
) as v(block_name, discipline, topic_order, topic_text)
on conflict (edition_id, discipline, topic_order) do update set block_name=excluded.block_name, topic_text=excluded.topic_text, content_status='current';

